<script setup lang="ts">
import { reactive, ref, nextTick } from 'vue'; import type { VForm } from 'vuetify/components'; import { useFormSubmission } from '@/composables/useFormSubmission'; import { email, required } from '@/utils/validation'; import FormIntro from './FormIntro.vue'
const form=ref<InstanceType<typeof VForm>>();const success=ref<HTMLElement>();const model=reactive({name:'',email:'',subject:'',message:''});const{status,submit,dismiss}=useFormSubmission()
async function handleSubmit(){dismiss();const result=await form.value?.validate();if(!result?.valid)return;await submit(()=>form.value?.reset());await nextTick();success.value?.focus()}
</script>
<template><v-card class="form-shell"><FormIntro title="Send a general enquiry" description="For questions that do not fit the two service forms, send us a short message."/><div v-if="status==='success'" ref="success" tabindex="-1" role="status" class="success-panel"><h3>Thank you—your message has been captured.</h3><p>This prototype has simulated a successful submission.</p><v-btn variant="text" color="primary" @click="dismiss">Send another message</v-btn></div><v-form v-else ref="form" @submit.prevent="handleSubmit"><div class="form-grid"><v-text-field v-model="model.name" label="Full name" :rules="[required('Full name')]" required/><v-text-field v-model="model.email" label="Email" type="email" :rules="[required('Email'),email]" required/><v-text-field v-model="model.subject" class="full" label="Subject" :rules="[required('Subject')]" required/><v-textarea v-model="model.message" class="full" label="Message" rows="5" :rules="[required('Message')]" required/></div><v-btn type="submit" color="primary" size="large" :loading="status==='loading'">Send Enquiry</v-btn></v-form></v-card></template>
<style scoped>h3{margin:0 0 6px}.success-panel p{margin:0 0 12px}</style>
